// Calculate Trend: Week-over-week at-risk deal comparison

const summary = $input.first().json;
const currentAtRisk = summary.totalAtRisk || 0;

// Hardcode previous week for now
const PREVIOUS_WEEK_AT_RISK = 8;

// Calculate trend
const trend = currentAtRisk - PREVIOUS_WEEK_AT_RISK;
const trendPercent = PREVIOUS_WEEK_AT_RISK > 0 
  ? Math.round((trend / PREVIOUS_WEEK_AT_RISK) * 100) 
  : 0;

let trendEmoji, trendLabel;
if (trend > 0) {
  trendEmoji = '🔴';
  trendLabel = 'Worse';
} else if (trend < 0) {
  trendEmoji = '🟢';
  trendLabel = 'Better';
} else {
  trendEmoji = '⚪';
  trendLabel = 'Flat';
}

const trendString = trend !== 0 
  ? `${trendEmoji} ${trend > 0 ? '+' : ''}${trend} deals (was ${PREVIOUS_WEEK_AT_RISK})`
  : `${trendEmoji} Flat (was ${PREVIOUS_WEEK_AT_RISK} deals)`;

return {
  ...summary,  // Pass through all summary data (totalAtRisk, byStage, topRiskDeals, etc.)
  currentAtRisk,
  previousWeekAtRisk: PREVIOUS_WEEK_AT_RISK,
  trend,
  trendPercent,
  trendEmoji,
  trendLabel,
  trendString
};

// Calculate Stage Stats: Average days-in-stage per stage, tiered revenue-at-risk, identify bottlenecks
const deals = $input.all().map(d => d.json);
const stages = ['Qualified Lead', 'Discovery', 'Proposal/Demo', 'Negotiation'];
const stageStats = {};

let slowestStage = null;
let slowestAvgDays = 0;
let fastestStage = null;
let fastestAvgDays = Infinity;

let totalHighRiskRevenue = 0;
let totalMediumRiskRevenue = 0;
let totalHighRiskCount = 0;
let totalMediumRiskCount = 0;

stages.forEach(stage => {
  const stageDeals = deals.filter(
    d => d.stage === stage && d.risk_level !== 'CLOSED' && d.risk_level !== 'UNKNOWN'
  );

  if (stageDeals.length > 0) {
    const totalDays = stageDeals.reduce((sum, d) => sum + d.days_in_stage, 0);
    const avgDays = Math.round(totalDays / stageDeals.length);

    const highRiskDeals = stageDeals.filter(d => d.risk_level === 'HIGH');
    const mediumRiskDeals = stageDeals.filter(d => d.risk_level === 'MEDIUM');
    const okDeals = stageDeals.filter(d => d.risk_level === 'OK');

    const highRiskCount = highRiskDeals.length;
    const mediumRiskCount = mediumRiskDeals.length;
    const okCount = okDeals.length;

    // Calculate revenue at risk by tier
    const highRiskRevenue = highRiskDeals.reduce((sum, d) => sum + d.revenue_at_risk, 0);
    const mediumRiskRevenue = mediumRiskDeals.reduce((sum, d) => sum + d.revenue_at_risk, 0);

    stageStats[stage] = {
      avgDays,
      dealCount: stageDeals.length,
      highRisk: highRiskCount,
      mediumRisk: mediumRiskCount,
      ok: okCount,
      atRiskCount: highRiskCount + mediumRiskCount,
      highRiskRevenue,
      mediumRiskRevenue,
      totalStageRevenue: stageDeals.reduce((sum, d) => sum + d.revenue_at_risk, 0)
    };

    // Accumulate totals
    totalHighRiskRevenue += highRiskRevenue;
    totalMediumRiskRevenue += mediumRiskRevenue;
    totalHighRiskCount += highRiskCount;
    totalMediumRiskCount += mediumRiskCount;

    // Track slowest/fastest
    if (avgDays > slowestAvgDays) {
      slowestAvgDays = avgDays;
      slowestStage = stage;
    }
    if (avgDays < fastestAvgDays) {
      fastestAvgDays = avgDays;
      fastestStage = stage;
    }
  } else {
    stageStats[stage] = {
      avgDays: 0,
      dealCount: 0,
      highRisk: 0,
      mediumRisk: 0,
      ok: 0,
      atRiskCount: 0,
      highRiskRevenue: 0,
      mediumRiskRevenue: 0,
      totalStageRevenue: 0
    };
  }
});

const slaThresholds = {
  'Qualified Lead': 5,
  'Discovery': 5,
  'Proposal/Demo': 21,
  'Negotiation': 14
};

const bottlenecks = [];
stages.forEach(stage => {
  const stats = stageStats[stage];
  const sla = slaThresholds[stage];

  if (stats.dealCount > 0 && stats.avgDays > sla) {
    bottlenecks.push({
      stage,
      avgDays: stats.avgDays,
      sla,
      daysOverSla: stats.avgDays - sla,
      dealCount: stats.dealCount,
      atRiskCount: stats.atRiskCount,
      highRiskRevenue: stats.highRiskRevenue,
      mediumRiskRevenue: stats.mediumRiskRevenue
    });
  }
});

const bottleneckWarnings = bottlenecks
  .sort((a, b) => b.daysOverSla - a.daysOverSla)
  .map(b => `${b.stage}: ${b.avgDays} days avg (SLA: ${b.sla}, +${b.daysOverSla} days over)`)
  .join('\n');

return {
  stageStats,
  slowestStage,
  slowestAvgDays,
  fastestStage,
  fastestAvgDays,
  bottleneckCount: bottlenecks.length,
  bottlenecks,
  bottleneckWarnings,
  // Summary-level risk metrics
  highRiskRevenue: totalHighRiskRevenue,
  mediumRiskRevenue: totalMediumRiskRevenue,
  highRiskCount: totalHighRiskCount,
  mediumRiskCount: totalMediumRiskCount,
  totalAtRiskRevenue: totalHighRiskRevenue + totalMediumRiskRevenue
};

// Calculate Days & Risk - COMBINED (with stage mapping, tiered revenue-at-risk)
const stageNameMap = {
  "appointmentscheduled": "Qualified Lead",
  "qualifiedtobuy": "Discovery",
  "presentationscheduled": "Proposal/Demo",
  "decisionmakerboughtin": "Negotiation",
  "closedwon": "Closed Won",
  "closedlost": "Closed Lost"
};

// SLA thresholds in days
const slaThresholds = {
  "Qualified Lead": 5,
  "Discovery": 5,
  "Proposal/Demo": 21,
  "Negotiation": 14
};

// Revenue-at-risk loss probabilities
const lossProability = {
  "HIGH": 0.40,      // 40% for deals significantly overdue
  "MEDIUM": 0.15,    // 15% for deals aging but not critical
  "OK": 0            // 0% for on-track deals
};

const deals = $input.all();
const today = new Date();

return deals.map(deal => {
  // Extract and normalize deal data
  const deal_id = deal.json.dealId;
  const deal_name = deal.json.properties.dealname?.value || 'N/A';
  const stage_id = deal.json.properties.dealstage?.value || 'Unknown';
  const stage = stageNameMap[stage_id] || 'Unknown Stage';
  const amount = parseFloat(deal.json.properties.amount?.value || 0);
  const stage_entry_date = deal.json.properties['hs_v2_date_entered_current_stage']?.value || null;
  const owner_id = deal.json.properties.hubspot_owner_id?.value || null;

  // Calculate days in stage
  let stage_date = stage_entry_date ? new Date(parseInt(stage_entry_date)) : null;
  let days_in_stage = stage_date ? Math.floor((today - stage_date) / (1000 * 60 * 60 * 24)) : 0;

  // Get SLA threshold for this stage
  let sla_threshold = slaThresholds[stage] || null;

  // Determine risk level based on SLA
  let risk_level;
  if (stage === 'Closed Won' || stage === 'Closed Lost') {
    risk_level = 'CLOSED';
  } else if (sla_threshold === null) {
    risk_level = 'UNKNOWN';
  } else if (days_in_stage > sla_threshold) {
    risk_level = 'HIGH';
  } else if (days_in_stage > (sla_threshold * 0.7)) {
    risk_level = 'MEDIUM';
  } else {
    risk_level = 'OK';
  }

  // Calculate tiered revenue at risk
  let revenue_at_risk = amount * (lossProability[risk_level] || 0);

  return {
    deal_id,
    deal_name,
    stage,
    stage_id,
    amount,
    stage_entry_date,
    owner_id,
    days_in_stage,
    sla_threshold,
    risk_level,
    revenue_at_risk,
    stage_date: stage_date ? stage_date.toISOString().split('T')[0] : null
  };
});

const deals = $input.all().map(d => d.json);

const highRiskDeals = deals.filter(d => d.risk_level === 'HIGH');
const mediumRiskDeals = deals.filter(d => d.risk_level === 'MEDIUM');

const highRiskCount = highRiskDeals.length;
const mediumRiskCount = mediumRiskDeals.length;
const totalAtRisk = highRiskCount + mediumRiskCount;

// Calculate tiered revenue at risk
const highRiskRevenue = highRiskDeals.reduce((sum, d) => sum + d.revenue_at_risk, 0);
const mediumRiskRevenue = mediumRiskDeals.reduce((sum, d) => sum + d.revenue_at_risk, 0);
const totalRevenueAtRisk = highRiskRevenue + mediumRiskRevenue;

const byStage = {
  'Discovery': deals.filter(d => d.stage === 'Discovery' && d.risk_level !== 'OK').length,
  'Qualified Lead': deals.filter(d => d.stage === 'Qualified Lead' && d.risk_level !== 'OK').length,
  'Proposal/Demo': deals.filter(d => d.stage === 'Proposal/Demo' && d.risk_level !== 'OK').length,
  'Negotiation': deals.filter(d => d.stage === 'Negotiation' && d.risk_level !== 'OK').length
};

const topRiskDeals = deals
  .filter(d => d.risk_level === 'HIGH' || d.risk_level === 'MEDIUM')  // ← Include MEDIUM
  .sort((a, b) => b.days_in_stage - a.days_in_stage)
  .slice(0, 3);

return {
  totalAtRisk,
  highRiskCount,
  mediumRiskCount,
  highRiskRevenue: Math.round(highRiskRevenue),
  mediumRiskRevenue: Math.round(mediumRiskRevenue),
  totalRevenueAtRisk: Math.round(totalRevenueAtRisk),
  byStage,
  topRiskDeals
};
